const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed=[{id:'khoi',name:'Nguyễn Minh Khôi',avatar:'👨‍🎓',role:'Broke',unread:1,saved:false,messages:[{mine:false,text:'Chào bạn! Mình đã cập nhật câu chuyện và mục tiêu trả nợ của mình rồi.',time:'19:10'},{mine:true,text:'Cảm ơn bạn đã chia sẻ. Mình có thể đồng hành với bạn theo cách nào?',time:'19:22'},{mine:false,text:'Chỉ cần có người lắng nghe là mình đã thấy nhẹ lòng hơn rất nhiều.',time:'19:34'},{mine:true,text:'Từng bước một nhé. Bạn không phải đi một mình.',time:'19:48'},{mine:false,text:'Mình cảm ơn bạn nhiều! 🙏',time:'19:48'}]},{id:'thao',name:'Lê Thị Thanh Thảo',avatar:'👩‍👧',role:'Broke',unread:1,saved:false,messages:[{mine:false,text:'Cảm ơn Bro rất nhiều! Một chút động viên đã giúp mình có thêm hy vọng. 🌱',time:'18:25'}]},{id:'nam',name:'Trần Hoàng Nam',avatar:'🌱',role:'Bro',unread:0,saved:true,messages:[{mine:false,text:'Mình rất thích tinh thần của cộng đồng. Chúc bạn có một khởi đầu mới thật tốt.',time:'Hôm qua'}]}];
let conversations=structuredClone(seed),active='khoi',filter='all',query='',api;
try{const data=JSON.parse(localStorage.getItem('debtfreelately-messages'));if(Array.isArray(data)&&data.length&&data.every(c=>typeof c.id==='string'&&typeof c.name==='string'&&Array.isArray(c.messages)&&c.messages.every(m=>typeof m.text==='string'&&typeof m.time==='string')))conversations=data;}catch{}
function persist(){try{localStorage.setItem('debtfreelately-messages',JSON.stringify(conversations));return true;}catch{api.toast('Không thể lưu tin nhắn trên thiết bị này.');return false;}}
export function initMessages(callbacks){api=callbacks;const root=document.createElement('section');root.id='messages-page';root.setAttribute('aria-label','Tin nhắn');document.body.append(root);root.addEventListener('click',ev=>{const b=ev.target.closest('[data-msg]');if(!b)return;const action=b.dataset.msg;if(action==='profile')exit('profile');if(action==='discover')exit('discover');if(action==='role')exit('role');if(action==='open'){active=b.dataset.id;const c=conversations.find(c=>c.id===active);if(c)c.unread=0;persist();root.classList.add('chat-open');render();}if(action==='filter'){filter=b.dataset.filter;render();}if(action==='save'){const c=conversations.find(c=>c.id===active);if(c){c.saved=!c.saved;persist();render();}}if(action==='back'){root.classList.remove('chat-open');}if(action==='info')info();if(action==='emoji'){const field=document.querySelector('#message-input');if(field){field.setRangeText(' 🌱',field.selectionStart,field.selectionEnd,'end');field.focus();}}if(action==='new')newChat();});render();}
function exit(target){document.body.classList.remove('messages-mode');if(target==='profile')api.profile();if(target==='discover')api.discover();if(target==='role')api.role();}
export function showMessages(){document.body.classList.remove('onboarding','broke-mode','debts-mode','card-wizard-mode','registration-mode','bros-join-mode');document.body.classList.add('messages-mode');active=conversations.find(c=>c.id===active)?.id||conversations[0]?.id;const c=conversations.find(c=>c.id===active);if(c)c.unread=0;persist();render();window.scrollTo(0,0);}
function render(){const root=document.querySelector('#messages-page');if(!root)return;const c=conversations.find(c=>c.id===active);const unread=conversations.filter(c=>c.unread>0).length;root.innerHTML=`<header class="msg-header"><a class="msg-logo" href="#" data-msg="profile"><img src="assets/debtfreelately-logo-transparent.png" alt="DebtFreeLately"></a><nav><button data-msg="profile">♙ Trang cá nhân</button><button data-msg="discover">♡ Khám phá câu chuyện</button><button data-msg="role">⇄ Đổi vai trò</button></nav></header><div class="msg-workspace"><section class="conversation-panel"><div class="conversation-title"><h1>Tin nhắn</h1><button data-msg="new" aria-label="Tạo hội thoại thử nghiệm" title="Tạo hội thoại thử nghiệm">＋</button></div><label class="msg-search"><span>⌕</span><input id="message-search" aria-label="Tìm hội thoại" placeholder="Tìm tên hoặc tin nhắn…" value="${esc(query)}"></label><div class="message-filters"><button data-msg="filter" data-filter="all" class="${filter==='all'?'active':''}">Tất cả</button><button data-msg="filter" data-filter="unread" class="${filter==='unread'?'active':''}">Chưa đọc (${unread})</button><button data-msg="filter" data-filter="saved" class="${filter==='saved'?'active':''}">Đã lưu</button></div><div id="conversation-list"></div><p class="msg-local-note">Bản thử nghiệm · Hội thoại minh họa<br>Tin nhắn chỉ lưu trên trình duyệt của bạn.</p></section><section class="chat-panel">${c?`<div class="chat-heading"><button class="msg-back" data-msg="back" aria-label="Quay lại danh sách">‹</button><div class="chat-avatar">${esc(c.avatar||'🌱')}</div><div class="chat-person"><h2>${esc(c.name)}</h2><span><i></i> Hội thoại mẫu · ${esc(c.role||'Bro')}</span></div><div class="chat-tools"><button data-msg="save" aria-label="${c.saved?'Bỏ lưu':'Lưu'} hội thoại" title="${c.saved?'Bỏ lưu':'Lưu'} hội thoại">${c.saved?'★':'☆'}</button><button data-msg="info" aria-label="Thông tin hội thoại" title="Thông tin hội thoại">ⓘ</button></div></div><div class="chat-log" id="chat-log" role="log" aria-label="Nội dung tin nhắn"><div class="chat-day"><span>Hội thoại thử nghiệm</span></div>${c.messages.map(m=>`<div class="message-row ${m.mine?'outgoing':'incoming'}">${m.mine?'':`<div class="message-avatar">${esc(c.avatar||'🌱')}</div>`}<div class="message-body"><div class="message-bubble">${esc(m.text)}</div><div class="message-time">${esc(m.time)}${m.mine?' · Lưu trên thiết bị':''}</div></div></div>`).join('')}</div><form class="message-composer" id="message-form"><button type="button" data-msg="emoji" aria-label="Thêm biểu tượng cây non" title="Thêm 🌱">☺</button><textarea id="message-input" aria-label="Nhập tin nhắn" placeholder="Nhập tin nhắn…" rows="1" maxlength="2000" required></textarea><button class="message-send" aria-label="Lưu tin nhắn thử nghiệm" title="Lưu tin nhắn thử nghiệm">➤</button></form><div class="composer-caption">Chỉ lưu trên thiết bị · Chưa gửi đến người khác · Enter để lưu, Shift + Enter xuống dòng</div>`:'<div class="message-empty">Chọn một hội thoại để bắt đầu.</div>'}</section></div>`;renderList();document.querySelector('#message-search').oninput=ev=>{query=ev.target.value;renderList();};const form=document.querySelector('#message-form');if(form){form.onsubmit=ev=>{ev.preventDefault();send();};document.querySelector('#message-input').addEventListener('keydown',ev=>{if(ev.key==='Enter'&&!ev.shiftKey&&!ev.isComposing){ev.preventDefault();send();}});}const log=document.querySelector('#chat-log');if(log)log.scrollTop=log.scrollHeight;}
function renderList(){const q=query.trim().toLocaleLowerCase('vi');const items=conversations.filter(c=>(filter!=='unread'||c.unread>0)&&(filter!=='saved'||c.saved)&&`${c.name} ${c.messages.map(m=>m.text).join(' ')}`.toLocaleLowerCase('vi').includes(q));document.querySelector('#conversation-list').innerHTML=items.length?items.map(c=>{const m=c.messages.at(-1);return `<button class="conversation-item ${c.id===active?'selected':''}" data-msg="open" data-id="${esc(c.id)}"><div class="chat-avatar">${esc(c.avatar||'🌱')}</div><div class="conversation-preview"><div><strong>${esc(c.name)}</strong><time>${esc(m?.time||'Mới')}</time></div><div><p>${esc(m?.text||'Chưa có tin nhắn.')}</p>${c.unread?`<b>${c.unread}</b>`:c.saved?'<span class="conversation-star">★</span>':''}</div></div></button>`;}).join(''):'<div class="message-empty">Không có hội thoại phù hợp.</div>';}
function send(){const field=document.querySelector('#message-input'),text=field.value.trim();if(!text)return;const c=conversations.find(c=>c.id===active);if(!c)return;c.messages.push({mine:true,text:text.slice(0,2000),time:new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date())});persist();render();document.querySelector('#message-input').focus();}
function info(){const c=conversations.find(c=>c.id===active);api.modal(`<div class="eyebrow">THÔNG TIN HỘI THOẠI</div><h2>${esc(c?.name)}</h2><p>Đây là hội thoại minh họa giao diện. Tin nhắn bạn nhập chỉ lưu trên trình duyệt này, không được gửi tới người thật.</p><div class="info-box">Gọi thoại, gọi video và đính kèm tệp sẽ được bổ sung sau khi có tài khoản và máy chủ nhắn tin.</div>`);}
function newChat(){api.modal('<div class="eyebrow">HỘI THOẠI THỬ NGHIỆM</div><h2>Một kết nối mới.</h2><p>Tạo hội thoại cục bộ để thử giao diện, không tìm hoặc liên hệ người thật.</p><form id="new-chat-form"><label for="new-chat-name">Tên hiển thị</label><input id="new-chat-name" name="name" maxlength="60" required><button class="dark">Tạo hội thoại thử nghiệm</button></form>');document.querySelector('#new-chat-form').onsubmit=ev=>{ev.preventDefault();const name=new FormData(ev.target).get('name').trim();if(!name)return;const id=crypto.randomUUID();conversations.unshift({id,name,avatar:'🌱',role:'Bro',unread:0,saved:false,messages:[]});active=id;filter='all';query='';persist();api.close();document.querySelector('#messages-page').classList.add('chat-open');render();};}


export function openCardConversation({id,name,title}){const contactId='card-contact:'+id;let conversation=conversations.find(c=>c.id===contactId);if(!conversation){conversation={id:contactId,name,avatar:'🌱',role:'Broke',unread:0,saved:false,messages:[],notificationDraft:{title,createdAt:new Date().toISOString(),status:'local-only'}};conversations.unshift(conversation);}active=contactId;filter='all';query='';persist();showMessages();document.querySelector('#messages-page').classList.add('chat-open');const field=document.querySelector('#message-input');field.value=`Chào bạn, mình muốn tìm hiểu thêm về khoản nợ “${title}” và cách có thể giúp bạn.`;field.focus();api.toast('Đã mở hội thoại và lưu yêu cầu liên hệ trên thiết bị. Chưa gửi thông báo thật.');}
export function openSupporterMessage({id,name,initials='♡',color='gold'}){const contactId='supporter:'+id;let conversation=conversations.find(c=>c.id===contactId);if(!conversation){conversation={id:contactId,name,avatar:initials,role:'Bros',unread:0,saved:false,messages:[]};conversations.unshift(conversation);}const miniLog=()=>conversation.messages.slice(-5).map(message=>`<div class="supporter-mini-bubble">${esc(message.text)}<small>${esc(message.time)} · Lưu trên thiết bị</small></div>`).join('');api.modal(`<div class="supporter-mini-profile"><div class="supporter-mini-avatar ${esc(color)}" role="img" aria-label="Ảnh đại diện minh họa của ${esc(name)}">${esc(initials)}</div><h2>${esc(name)}</h2><p>Người đã đồng hành cùng bạn ♡</p></div><div class="supporter-mini-log" id="supporter-mini-log" role="log" aria-label="Tin nhắn với ${esc(name)}">${miniLog()}</div><form id="supporter-mini-form"><label for="supporter-mini-input" class="supporter-mini-label">Gửi lời nhắn cho ${esc(name)}</label><div class="supporter-mini-composer"><input id="supporter-mini-input" name="message" maxlength="2000" placeholder="Nhập tin nhắn…" autocomplete="off" required><button aria-label="Gửi tin nhắn cho ${esc(name)}">➤</button></div></form><p class="supporter-mini-note">Hồ sơ hỗ trợ minh họa · Tin nhắn chỉ lưu trên thiết bị, chưa gửi cho người thật.</p>`);document.querySelector('#supporter-mini-form').onsubmit=event=>{event.preventDefault();const field=document.querySelector('#supporter-mini-input'),text=field.value.trim();if(!text)return;conversation.messages.push({mine:true,text,time:new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Australia/Sydney'}).format(new Date())});const saved=persist();document.querySelector('#supporter-mini-log').innerHTML=miniLog();field.value='';field.focus();if(saved)api.toast('Đã lưu tin nhắn trong mục Tin nhắn. Chưa gửi đến người thật.');};}
